import { API, graphqlOperation } from "aws-amplify";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
export default {
  data() {
    return {
      listHeight: 0,
      searchQuery: "",
      groupName: "",
      allusers: [],
      model: [],
      selectedUsers: [],
      loading: false,
      channelVisbility: null,
      visibilityUsers: [],
      isTransitioning: false,
      selectionTimeout: null
    };
  },
  mixins: [get_all_org_users],
  // computed: {
  //   filteredUsers() {
